export const loadPuzzlesByKey = (key: string): Puzzle[] => {
  const loader = loaders[key]
  if (!loader) return []
  return loader()
}

export const loadAllPuzzles = (): Puzzle[] => {
  const combined = new Map<string, Puzzle>()

  for (const item of puzzleManifest) {
    const puzzles = loadPuzzlesByKey(item.key)
    for (const puzzle of puzzles) {
      const k = `${puzzle.id}:${puzzle.category}`
      if (!combined.has(k)) combined.set(k, puzzle)
    }
  }

  return [...combined.values()]
}
